import {readFileSync,writeFileSync,realpathSync} from 'node:fs';
import {createHash} from 'node:crypto';
const [imagePath,summaryPath,emitPath]=process.argv.slice(2);
if(!imagePath||!summaryPath)throw Error('Expected IMAGE CPU_SUMMARY [FRESH_DIAGNOSTIC_IMAGE]');
const parserModule={exports:{}};
const parserSource=process.binding('natives')['internal/deps/acorn/acorn/dist/acorn'];
new Function('exports','module',parserSource)(parserModule.exports,parserModule);
const source=readFileSync(imagePath,'utf8'),summary=JSON.parse(readFileSync(summaryPath,'utf8'));
const program=parserModule.exports.parse(source,{ecmaVersion:'latest',sourceType:'module',locations:true});
const hash=value=>createHash('sha256').update(value).digest('hex');
function children(node){const out=[];for(const [key,value]of Object.entries(node)){if(key==='loc')continue;if(Array.isArray(value)){for(const child of value)if(child&&typeof child.type==='string')out.push(child);}else if(value&&typeof value.type==='string')out.push(value);}return out;}
function scan(root,visit){const stack=[root];while(stack.length){const node=stack.pop();visit(node);stack.push(...children(node));}}
const declarations=new Map(),primitiveBodies=new Map();
for(const node of program.body){if(node.type==='FunctionDeclaration')declarations.set(node.id.name,node);if(node.type==='VariableDeclaration')for(const d of node.declarations)if(d.id.type==='Identifier'&&d.id.name.startsWith('$p_')&&['ArrowFunctionExpression','FunctionExpression'].includes(d.init?.type))primitiveBodies.set(d.id.name,d.init);}
const forbidden=new Set(['$TAIL_PENDING','$CALL_PENDING','$LEAVE_PENDING','$BEND_TAIL','$sp','$ksp','$tailFn','$tailCount','$stArgs','$kFn','$kBase','$kKind','$tailArgs','$tailRest','$tailUnary','$leaveThunk']);
function noSuspensionSyntax(body,allowedCalls){let reason;scan(body,node=>{if(reason)return;if(['FunctionExpression','ArrowFunctionExpression','FunctionDeclaration','ClassExpression','ClassDeclaration','AwaitExpression','YieldExpression','NewExpression','ImportExpression','WithStatement'].includes(node.type))reason=node.type;else if(node.type==='Identifier'&&forbidden.has(node.name))reason='scheduler-global:'+node.name;else if(node.type==='CallExpression'&&(node.callee.type!=='Identifier'||!allowedCalls.has(node.callee.name)))reason='unproved-call:'+source.slice(node.callee.start,node.callee.end);});return reason;}
const terminalPrimitives=new Set();
for(const [name,node]of primitiveBodies)if(!noSuspensionSyntax(node.body,new Set()))terminalPrimitives.add(name);
for(const [name,node]of declarations)if(name.startsWith('$p_')&&!noSuspensionSyntax(node.body,new Set()))terminalPrimitives.add(name);
const leaves=new Set(),leafRejections={};
for(const [name,node]of declarations){if(!/^\$b[0-9]+$/.test(name))continue;const reason=noSuspensionSyntax(node.body,terminalPrimitives);if(reason)leafRejections[reason]=(leafRejections[reason]??0)+1;else leaves.add(name);}
const sites=[],patches=[],parentBodies=new Set(),continuations=new Set();
for(const [owner,fn]of declarations){if(!/^\$[bk][0-9]+$/.test(owner))continue;scan(fn.body,node=>{
 if(node.type!=='BlockStatement')return;
 for(let i=1;i<node.body.length;i++){
  const decl=node.body[i-1],attempt=node.body[i];
  if(decl.type!=='VariableDeclaration'||decl.declarations.length!==2||attempt.type!=='TryStatement'||attempt.finalizer||!attempt.handler||attempt.block.body.length!==1)continue;
  const [base,index]=decl.declarations,ret=attempt.block.body[0],done=ret.argument;
  if(base.id.type!=='Identifier'||index.id.type!=='Identifier'||base.init?.type!=='BinaryExpression'||base.init.operator!=='-'||base.init.left.type!=='Identifier'||base.init.left.name!=='$sp'||base.init.right.type!=='Literal'||!Number.isSafeInteger(base.init.right.value)||base.init.right.value<0)continue;
  if(index.init?.type!=='CallExpression'||index.init.callee.type!=='Identifier'||index.init.callee.name!=='$split_enter'||index.init.arguments.length!==2)continue;
  const [cont,kb]=index.init.arguments;
  if(cont.type!=='Identifier'||!/^\$k[0-9]+$/.test(cont.name)||kb.type!=='Identifier'||kb.name!==base.id.name)continue;
  if(ret.type!=='ReturnStatement'||done?.type!=='CallExpression'||done.callee.type!=='Identifier'||done.callee.name!=='$split_done'||done.arguments.length!==3)continue;
  const [call,ki,depth]=done.arguments;
  if(call.type!=='CallExpression'||call.callee.type!=='Identifier'||!leaves.has(call.callee.name)||ki.type!=='Identifier'||ki.name!==index.id.name)continue;
  if(depth.type!=='BinaryExpression'||depth.operator!=='+'||depth.left.type!=='Identifier'||depth.left.name!=='$td'||depth.right.type!=='Literal'||depth.right.value!==1)continue;
  if(call.arguments.some(arg=>!['Identifier','Literal','BinaryExpression'].includes(arg.type)))continue;
  const code=source.slice(ret.start,ret.end),temporary='$g72Leaf_'+ret.start;
  if(source.includes(temporary))throw Error('Temporary collision');
  const replacement='const '+temporary+'='+source.slice(call.start,call.end)+';$sp='+base.id.name+';return '+cont.name+'('+temporary+','+base.id.name+','+source.slice(depth.start,depth.end)+');';
  const site={owner,callee:call.callee.name,continuation:cont.name,spillCount:base.init.right.value,line1:decl.loc.start.line,frameRange:[index.init.start,index.init.end],returnRange:[ret.start,ret.end],originalFrame:source.slice(index.init.start,index.init.end),originalReturn:code,replacement};
  sites.push(site);parentBodies.add(owner);continuations.add(cont.name);patches.push({start:index.init.start,end:index.init.end,text:'$ksp'},{start:ret.start,end:ret.end,text:replacement});
 }
});}
patches.sort((a,b)=>a.start-b.start);for(let i=1;i<patches.length;i++)if(patches[i-1].end>patches[i].start)throw Error('Overlapping AST edits');
const relevant=row=>{try{return realpathSync(new URL(row.url))===realpathSync(imagePath);}catch{return false;}};
const parentRows=summary.functions.filter(row=>relevant(row)&&parentBodies.has(row.functionName));
const continuationRows=summary.functions.filter(row=>relevant(row)&&continuations.has(row.functionName));
const result={kind:'CONSERVATIVE_AST_PROVEN_TERMINAL_LEAF_EAGER_FRAME_CENSUS',image:{path:realpathSync(imagePath),sha256:hash(source)},parser:'Acorn bundled in pinned Node '+process.versions.node,sourceBytes:Buffer.byteLength(source),terminalPrimitiveCount:terminalPrimitives.size,leafBodies:leaves.size,leafRejections,sites:sites.length,affectedParentBodies:parentBodies.size,continuations:continuations.size,parentExclusiveShare:parentRows.reduce((sum,row)=>sum+row.selfShare,0),continuationExclusiveShare:continuationRows.reduce((sum,row)=>sum+row.selfShare,0),parentRows,continuationRows,siteDetails:sites,invariants:['AST-proven terminal leaf: no scheduler globals, no closures, no opaque/member/foreign call, only call-free primitive functions','Only eager td<64 branch changes; original depth-exhausted fallback and all public aliases unchanged','Arguments/capture stores/native bodies/quantum64 unchanged; only split_enter frame and split_done marker checks removed','Original catch uses saved pre-frame ksp and split_abort; continuation and its exceptions remain','This is a counterfactual image, NOT source compiler, qualification, fixedpoint or product'],scope:'Affected-parent/continuation self shares contain semantic work; neither is removable overhead or speedup ceiling.'};
if(emitPath){let output='',at=0;for(const patch of patches){output+=source.slice(at,patch.start)+patch.text;at=patch.end;}output+=source.slice(at);parserModule.exports.parse(output,{ecmaVersion:'latest',sourceType:'module'});writeFileSync(emitPath,output,{flag:'wx'});result.diagnosticImage={path:realpathSync(emitPath),sha256:hash(output),bytes:Buffer.byteLength(output),ASTEdits:patches.length};}
console.log(JSON.stringify(result));

