import {readFileSync} from 'node:fs';
import {realpathSync} from 'node:fs';
import {mapImage,summarizeProfile} from './evals/selfhost_corpus_cpu.ts';
const image=realpathSync(process.argv[1]),profile=JSON.parse(readFileSync(process.argv[2],'utf8'));
const map=mapImage(readFileSync(image,'utf8')),result=summarizeProfile(profile,image,map);
console.log(JSON.stringify({kind:'EXISTING_G56_PHYSICAL_RULES_APPLIED_TO_G72_CPU_ONLY',scope:'Physicalsourcefamiliesonly;noNF/equalitysemanticexclusionorlogicalancestryinference',samples:result.samples,sampledMs:result.sampledMs,excludedSamples:result.excludedSamples,unattributedDurationMs:result.unattributedDurationMs,codeMap:{declarations:map.declarations.size,aliasedBodies:map.aliases.size,omissions:map.omissions.length},families:result.families.map(({functionIdentities,...row})=>({...row,functionCount:functionIdentities.length})),functions:result.functions}));
